    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, d;
    string s;
    cin >> n >> d >> s;

    vector<int> dist(n + 1, -1);
    queue<int> q;

    dist[1] = 0;
    q.push(1);

    while (!q.empty()) {
        int now = q.front();
