#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, d;
    cin >> n >> d;

    string s;
    cin >> s;

    vector<bool> accessible(n + 1, false), visited(n + 1, false);
    for (int i = 1; i <= n; ++i) {
        accessible[i] = (s[i - 1] == '1');
    }

    queue<pair<int, int>> q;
    q.push({1, 0});
    visited[1] = true;

    int minstep = -1;

    while (!q.empty()) {
        auto [position, steps] = q.front();
        q.pop();

        if (position == n) {
            minstep = steps;
            break;
        }

        for (int jump = 1; jump <= d && position + jump <= n; ++jump) {
            int next = position + jump;
            if (accessible[next] && !visited[next]) {
                visited[next] = true;
                q.push({next, steps + 1});
            }
        }
    }

    cout << minstep << '\n';
    return 0;
}

